import java.util.*;
public class Huffman {
    static class Node implements Comparable<Node> {
        char ch; int freq; Node left, right;
        Node(char c, int f) { ch=c; freq=f; }
        Node(int f, Node l, Node r) { freq=f; left=l; right=r; }
        public int compareTo(Node o) { return freq - o.freq; }
    }
    static void printCodes(Node root, String code) {
        if (root == null) return;
        if (root.left == null && root.right == null)
            System.out.println(root.ch + ": " + code);
        printCodes(root.left, code + "0");
        printCodes(root.right, code + "1");
    }
    public static void buildHuffman(char[] chars, int[] freqs) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < chars.length; i++) pq.add(new Node(chars[i], freqs[i]));
        while (pq.size() > 1) {
            Node l = pq.poll(), r = pq.poll();
            pq.add(new Node(l.freq + r.freq, l, r));
        }
        printCodes(pq.poll(), "");
    }
    public static void main(String[] args) {
        char[] chars = {'a','b','c','d','e','f'};
        int[]  freqs = {45, 13, 12, 16,  9,  5};
        buildHuffman(chars, freqs);
    }
}

