void huffman(vector<pair<char,int>>& v) {
    auto cmp = [](Node* a, Node* b){ return a->freq > b->freq; };
    priority_queue<Node*,vector<Node*>,decltype(cmp)> pq(cmp);
    for (auto& [c,f] : v) pq.push(new Node{c, f, nullptr, nullptr});
    while (pq.size() > 1) {
        auto l=pq.top(); pq.pop(); auto r=pq.top(); pq.pop();
        pq.push(new Node{0, l->freq+r->freq, l, r});
    }
    printCodes(pq.top());
}
